package main
import("fmt";"reflect";"github.com/minz/minzc/pkg/emulator";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/nanz";"github.com/minz/minzc/pkg/pipeline";"github.com/minz/minzc/pkg/z80asm")
func main(){source:=`fun wr16(arr:^u8,idx:u16,val:u16){var base:u16=idx*2
arr[base]=u8(val)
arr[base+1]=u8(val/256)}`;count:=0;for variant:=0;variant<2;variant++{m,e:=nanz.Parse(source,"wr16-independent.nanz");must(e);m.GraceRulePolicy=map[string]bool{};m.PointerWalkPolicy=map[string]bool{};m.InvariantBasePolicy=map[string]bool{};m.ForwardCopyPolicy=map[string]bool{};m.RegionComparePolicy=map[string]bool{};if variant==1{must(hir.ApplyHashmapWR16Prototype(m))};s,e:=pipeline.CompileHIRSteps(m,pipeline.Options{AssertMode:"none",UseHIRGrace:true});must(e);a,e:=z80asm.NewAssembler().AssembleString("ORG 0x8000\nCALL wr16\nDI\nHALT\n"+s.Assembly);must(e);if len(a.Errors)>0{panic(a.Errors)}
for _,idx:=range []uint16{0,1,255,256,32767,32768,32769,65534,65535}{for _,arr:=range []uint16{0,1,65534,65535}{for _,val:=range []uint16{0,255,256,0xABCD,65535}{low:=arr+idx*2;high:=low+1;if protected(int(low),len(a.Binary))||protected(int(high),len(a.Binary)){panic("fixture overlap")};memory:=make([]byte,65536);for j:=range memory{memory[j]=byte(j*37+11)};copy(memory[0x8000:],a.Binary);want:=append([]byte(nil),memory...);want[low]=byte(val);want[high]=byte(val>>8);platform:=emulator.NewRemogattoZ80WithScreen();platform.SetROMEnd(0);z:=platform.RemogattoZ80;z.Reset();z.SetSMCTracker(nil);must(z.LoadMemory(0,memory));p:=emulator.NewProfiler();z.SetProfiler(p);r:=emulator.Registers{PC:0x8000,SP:0xF000};mf:=s.MIR2Module.FuncByName("wr16");for k,arg:=range []uint16{arr,idx,val}{loc:=s.Allocation.Loc(mf.Contract.Params[k].Reg).Name;switch loc{case "HL":r.HL=arg;case "DE":r.DE=arg;case "BC":r.BC=arg;case "IX":r.IX=arg;case "IY":r.IY=arg;default:panic(loc)}};z.SetRegisters(r);lastW,lastR:=[65536]uint32{},[65536]uint32{};events:=[]uint16{}
for n:=0;!z.IsHalted();n++{if n>1000{panic("nohalt")};z.Step();delta:=[]uint16{};for j:=0;j<65536;j++{if !protected(j,len(a.Binary)){if p.ReadCount[j]!=lastR[j]{panic(fmt.Sprintf("unexpected dataread %d",j))};for k:=lastW[j];k<p.WriteCount[j];k++{delta=append(delta,uint16(j))}};lastW[j]=p.WriteCount[j];lastR[j]=p.ReadCount[j]};if len(delta)>1{panic(fmt.Sprintf("multiple datawrites in instruction %v",delta))};for _,addr:=range delta{value:=byte(val);if len(events)>0{value=byte(val>>8)};if z.GetMemory(addr)!=value{panic("wrongstepvalue")}};events=append(events,delta...)};if !reflect.DeepEqual(events,[]uint16{low,high}){panic(fmt.Sprintf("events %v",events))};for j:=range want{if j>=0xEF00&&j<0xF100{continue};if z.GetMemory(uint16(j))!=want[j]{panic(fmt.Sprintf("RAM %d",j))}};count++}}}}
fmt.Printf("PASS %d actualcalls bothvariants: singlebyteperinstruction writes low→high with exactvalue, no extra datareads/writes, fullRAM unchanged except explicit2bytes+stack\n",count)}
func protected(j,n int)bool{return j>=0x8000&&j<0x8000+n||j>=0xEF00&&j<0xF100};func must(e error){if e!=nil{panic(e)}}
